CREATE TABLE public.share_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('share_click','link_open')),channel text CHECK(channel IN ('link','story','confirm','direct')),question_id uuid REFERENCES public.questions(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.share_events TO anon,authenticated;
GRANT ALL ON public.share_events TO service_role;
ALTER TABLE public.share_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone logs anonymous share events" ON public.share_events FOR INSERT TO anon,authenticated WITH CHECK(created_at>now()-interval '1 minute');
CREATE INDEX share_events_kind_time ON public.share_events(kind,created_at);
CREATE OR REPLACE FUNCTION public.admin_stats(p_days int DEFAULT 14) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE d int:=LEAST(GREATEST(p_days,1),90); BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN jsonb_build_object('totals',jsonb_build_object('signups',(SELECT count(*) FROM public.profiles),'questions',(SELECT count(*) FROM public.questions),'votes',(SELECT count(*) FROM public.votes),'shares',(SELECT count(*) FROM public.share_events WHERE kind='share_click'),'opens',(SELECT count(*) FROM public.share_events WHERE kind='link_open')),'daily',(SELECT coalesce(jsonb_agg(row_to_json(t) ORDER BY t.day),'[]'::jsonb) FROM(SELECT g.day::date AS day,(SELECT count(*) FROM public.profiles p WHERE p.created_at::date=g.day::date) AS signups,(SELECT count(*) FROM public.questions q WHERE q.created_at::date=g.day::date) AS questions,(SELECT count(*) FROM public.votes v WHERE v.created_at::date=g.day::date) AS votes,(SELECT count(*) FROM public.share_events s WHERE s.kind='share_click' AND s.created_at::date=g.day::date) AS shares,(SELECT count(*) FROM public.share_events s WHERE s.kind='link_open' AND s.created_at::date=g.day::date) AS opens FROM generate_series(current_date-(d-1),current_date,interval '1 day') g(day)) t)); END $$;
REVOKE EXECUTE ON FUNCTION public.admin_stats(int) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_stats(int) TO authenticated;